def check_pw(pw):
    if len(pw) < 8:
        return False
    has_alpha = False
    has_digit = False
    for ch in pw:
        if ch.isalpha():
            has_alpha = True
        elif ch.isdigit():
            has_digit = True
    return has_alpha and has_digit   # 둘 다 있어야 True

