steps.solution:
def open_account(bank, name):
    if name in bank:                       # 중복 개설
        print("이미 있는 계좌입니다")
    else:
        bank[name] = 0
        print(f"{name} 계좌 개설")

def deposit(bank, name, money):
    if name not in bank:
        print("없는 계좌입니다")
    elif money <= 0:                       # 0 이하 금액
        print("금액이 올바르지 않습니다")
    else:
        bank[name] += money
        print(f"{name} 잔액: {bank[name]}")

def withdraw(bank, name, money):
    if name not in bank:
        print("없는 계좌입니다")
    elif money > bank[name]:               # 잔액 부족
        print("잔액이 부족합니다")
    else:
        bank[name] -= money
        print(f"{name} 잔액: {bank[name]}")

def stats(bank):
    if len(bank) == 0:                     # 빈 경우 먼저 (0 으로 나누기 방지)
        print("계좌가 없습니다")
        return
    total = sum(bank.values())
    avg = round(total / len(bank), 1)
    print(f"계좌 {len(bank)}개, 총액 {total}, 평균 {avg}")

bank = {}                                  # {이름: 잔액}
while True:
    menu = input()
    if menu == "1":
        open_account(bank, input())
    elif menu == "2":
        name = input()
        money = int(input())
        deposit(bank, name, money)
    elif menu == "3":
        name = input()
        money = int(input())
        withdraw(bank, name, money)
    elif menu == "4":
        stats(bank)
    elif menu == "0":
        print("종료합니다")
        break
    else:
        print("잘못된 메뉴입니다")
